'use strict';
const BUILD_HASH = "956ad3947137f649";
const PRECACHE = ["assets/index-5RPhwD6B.js","assets/index-DfOcZGHc.css","icons/apple-touch-icon-180.png","icons/icon-192.png","icons/icon-512.png","icons/icon-maskable-512.png","index.html","manifest.webmanifest"];
const NETWORK_TIMEOUT_MS = 3000;
const SCOPE = self.registration.scope;
const CACHE_PREFIX = 'neon-delve|' + SCOPE + '|';
const CACHE_NAME = CACHE_PREFIX + BUILD_HASH;
const INDEX_URL = new URL('index.html', SCOPE).href;
const ASSETS_URL = new URL('assets/', SCOPE).href;
const PRECACHED = new Set(PRECACHE.map((path) => new URL(path, SCOPE).href));

self.addEventListener('install', (event) => {
  // A new version installs in the background and then waits until the player presses "Restart".
  event.waitUntil(
    caches
      .open(CACHE_NAME)
      .then((cache) => cache.addAll(PRECACHE.map((path) => new Request(new URL(path, SCOPE).href, { cache: 'reload' })))),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((key) => key.startsWith(CACHE_PREFIX) && key !== CACHE_NAME).map((key) => caches.delete(key))),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  const path = url.origin + url.pathname;
  if (!path.startsWith(SCOPE)) return;
  if (request.mode === 'navigate' || path === SCOPE || path === INDEX_URL) {
    event.respondWith(networkFirst(request));
  } else if (path.startsWith(ASSETS_URL) || PRECACHED.has(path)) {
    event.respondWith(cacheFirst(request));
  }
});

// index.html: network first; after NETWORK_TIMEOUT_MS or a network error, the cached copy.
// The network copy is NOT written to the cache: each cache holds exactly one consistent version.
async function networkFirst(request) {
  const network = fetch(request);
  let timer;
  const timeout = new Promise((resolve) => {
    timer = setTimeout(resolve, NETWORK_TIMEOUT_MS, 'timeout');
  });
  const first = await Promise.race([network.catch(() => 'error'), timeout]);
  clearTimeout(timer);
  if (first !== 'timeout' && first !== 'error') return first;
  const cache = await caches.open(CACHE_NAME);
  const cached = await cache.match(INDEX_URL, { ignoreVary: true });
  return cached || network;
}

// assets/* and the other precached files: cache first.
async function cacheFirst(request) {
  const cache = await caches.open(CACHE_NAME);
  const cached = await cache.match(request, { ignoreVary: true });
  return cached || fetch(request);
}
